import XCTest
@testable import ColorComposerCore

/// Solver parity against the golden-vector corpus generated by the Elixir
/// `color_matching` service (viamin/color_matching#111, landed in #112).
///
/// The corpus is the authority on `ColorMatching.WeightedSquaredError`
/// behavior: per-candidate scores, the selected palette index, the winner's
/// error, tie-break evidence, and missing-measurement exclusions. These tests
/// replay every scenario through `WeightedSquaredErrorScorer` (and the
/// solver-level cases through `CompositionSolver`) and require exact
/// agreement — selections exactly, scores to within 1e-12. A failure here
/// means the Swift scorer and the Elixir solver have diverged.
///
/// Fixture: `Fixtures/parity-corpus-v1.json`, a verbatim copy of upstream
/// `priv/parity/v1/corpus.json` (upstream commit a82aec5). See
/// `docs/solver-parity-corpus.md` for how to refresh it.
final class SolverParityCorpusTests: XCTestCase {
    private static let scorer = WeightedSquaredErrorScorer()

    private static func loadCorpus() throws -> ParityCorpus {
        let url = URL(fileURLWithPath: #filePath, isDirectory: false)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/parity-corpus-v1.json", isDirectory: false)
        return try JSONDecoder().decode(ParityCorpus.self, from: Data(contentsOf: url))
    }

    private static func makeColor(_ vector: ParityVector) throws -> PaletteColor {
        var responses: [LightingCondition: IlluminationResponse] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                responses[condition] = IlluminationResponse(brightness: value)
            }
        }
        return PaletteColor(
            id: vector.index ?? 0,
            hex: vector.hexColor,
            rgb: try XCTUnwrap(RGBColor(hex: vector.hexColor), "corpus hex \(vector.hexColor) must parse"),
            responses: responses
        )
    }

    private static func makeTarget(_ vector: ParityVector) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                brightness[condition] = value
            }
        }
        return TargetResponseVector(brightness)
    }

    /// Corpus weights may carry unknown light sources (e.g. `ultraviolet`);
    /// `ChannelWeights` only models the five canonical conditions, so unknown
    /// keys are dropped by construction — exactly the expected behavior.
    private static func makeWeights(_ map: [String: Double]) -> ChannelWeights {
        ChannelWeights(
            white: map["white"] ?? 0,
            red: map["red"] ?? 0,
            green: map["green"] ?? 0,
            blue: map["blue"] ?? 0,
            lps: map["lps"] ?? 0
        )
    }

    /// Replays one scenario: every expected score, the selected index and hex,
    /// the winner's error, and the tie evidence. Selections must match
    /// exactly; numeric scores to within 1e-12.
    private func assertParity(
        _ scenario: ParityScenario,
        file: StaticString = #filePath,
        line: UInt = #line
    ) throws {
        let palette = try scenario.palette.map { try Self.makeColor($0) }
        let target = Self.makeTarget(scenario.target)
        let weights = Self.makeWeights(scenario.weights)
        let scored: [ScorerResult] = palette.map {
            Self.scorer.score(candidate: $0, target: target, weights: weights)
        }

        try assertScores(scored, match: scenario.expected.scores, scenario: scenario.id, file: file, line: line)
        try assertSelection(scored, in: scenario, file: file, line: line)
    }

    private func assertScores(
        _ scored: [ScorerResult],
        match expected: [ParityExpectedScore],
        scenario: String,
        file: StaticString,
        line: UInt
    ) throws {
        XCTAssertEqual(
            scored.count, expected.count,
            "scenario \(scenario): candidate count must match expected scores",
            file: file, line: line
        )
        for (index, pair) in zip(scored, expected).enumerated() {
            XCTAssertEqual(pair.1.index, index, "scenario \(scenario): score entries must be palette-ordered", file: file, line: line)
            switch (pair.0, pair.1.score) {
            case (.excluded, .excluded):
                continue
            case (.score(let actual), .score(let expectedValue)):
                XCTAssertEqual(
                    actual, expectedValue, accuracy: 1e-12,
                    "scenario \(scenario): candidate \(index) score",
                    file: file, line: line
                )
            case (.excluded, .score(let expectedValue)):
                XCTFail("scenario \(scenario): candidate \(index) excluded, expected score \(expectedValue)", file: file, line: line)
            case (.score(let actual), .excluded):
                XCTFail("scenario \(scenario): candidate \(index) scored \(actual), expected excluded", file: file, line: line)
            }
        }
    }

    private func assertSelection(
        _ scored: [ScorerResult],
        in scenario: ParityScenario,
        file: StaticString,
        line: UInt
    ) throws {
        let rankable: [(index: Int, score: Double)] = scored.enumerated().compactMap {
            guard case .score(let value) = $0.element else { return nil }
            return (index: $0.offset, score: value)
        }
        // Earliest-wins selection, stated explicitly: the first palette index
        // achieving the minimum score. This is the policy under test, so it is
        // computed openly rather than borrowed from min(by:) semantics.
        let bestScore = rankable.map(\.score).min()
        let selected = bestScore.flatMap { best in rankable.first { $0.score == best }?.index }

        XCTAssertEqual(
            selected, scenario.expected.selectedIndex,
            "scenario \(scenario): selected index (earliest wins)",
            file: file, line: line
        )
        if let selected {
            XCTAssertEqual(
                scenario.palette[selected].hexColor, scenario.expected.selectedHexColor,
                "scenario \(scenario): selected hex color",
                file: file, line: line
            )
            if let expectedError = scenario.expected.error,
               let winnerScore = rankable.first { $0.index == selected }?.score {
                XCTAssertEqual(
                    winnerScore, expectedError, accuracy: 1e-12,
                    "scenario \(scenario): winning error",
                    file: file, line: line
                )
            }
        } else {
            XCTAssertNil(scenario.expected.selectedHexColor, "scenario \(scenario): no selection expected", file: file, line: line)
        }

        let tiedIndices = bestScore.map { best in rankable.filter { $0.score == best }.map(\.index) } ?? []
        XCTAssertEqual(tiedIndices, scenario.expected.tiedIndices, "scenario \(scenario): tied indices", file: file, line: line)
        XCTAssertEqual(
            tiedIndices.count > 1, scenario.expected.tieBroke ?? false,
            "scenario \(scenario): tie_broke flag",
            file: file, line: line
        )
    }

    // MARK: - Corpus stamp

    /// The corpus declares the semantics it was generated under. If upstream
    /// changes the stamp, this fails loudly instead of replaying a corpus
    /// whose meaning has silently changed — refresh the fixture (see
    /// docs/solver-parity-corpus.md) and re-review.
    func testCorpusStampMatchesConsumedSemantics() throws {
        let corpus = try Self.loadCorpus()
        XCTAssertEqual(corpus.algorithmVersion, 1)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, LightingCondition.all.map(\.rawValue))
    }

    // MARK: - Exhaustive replay

    func testReplaysEveryScenarioWithExactAgreement() throws {
        let corpus = try Self.loadCorpus()
        XCTAssertGreaterThanOrEqual(corpus.scenarios.count, 12, "upstream may only append scenarios; a shrink means the fixture is stale")
        for scenario in corpus.scenarios {
            try assertParity(scenario)
        }
    }

    // MARK: - Focused parity contracts

    /// Ties — including the three-way tie — must resolve to the earliest
    /// palette index, matching `IlluminantMatching.best_match/4`.
    func testTiesBreakToTheEarliestPaletteIndex() throws {
        let corpus = try Self.loadCorpus()
        let ties = corpus.scenarios.filter { $0.expected.tieBroke == true }
        XCTAssertGreaterThanOrEqual(ties.count, 4, "corpus must keep its intentional tie scenarios")
        for scenario in ties {
            XCTAssertEqual(scenario.expected.selectedIndex, scenario.expected.tiedIndices.min())
            XCTAssertEqual(scenario.expected.selectedIndex, scenario.expected.tiedIndices.first)
            try assertParity(scenario)
        }
    }

    /// A candidate missing a positively-weighted measurement is excluded —
    /// never scored as if the missing channel were zero brightness.
    func testMissingMeasurementsExcludeRatherThanCountAsZero() throws {
        let corpus = try Self.loadCorpus()
        for scenario in corpus.scenarios where scenario.id.contains("excluded") {
            try assertParity(scenario)
        }
        let targetMissing = try XCTUnwrap(corpus.scenarios.first { $0.id == "missing-target-excluded" })
        XCTAssertTrue(targetMissing.expected.scores.allSatisfy { $0.score == .excluded })
        XCTAssertNil(targetMissing.expected.selectedIndex)
    }

    /// A zero-weight channel neither excludes nor contributes: a candidate
    /// missing the unweighted channel ties exactly with a measured one.
    func testZeroWeightChannelNeitherExcludesNorContributes() throws {
        let corpus = try Self.loadCorpus()
        let scenario = try XCTUnwrap(corpus.scenarios.first { $0.id == "zero-weight-channel-missing" })
        try assertParity(scenario)
        XCTAssertEqual(scenario.expected.tiedIndices, [0, 1])
        XCTAssertEqual(scenario.expected.selectedIndex, 0)
    }

    /// Unknown light sources in the weights map (e.g. `ultraviolet`) are
    /// ignored: this scenario's palette and target match `distinct-errors`
    /// verbatim and must reproduce its scores exactly.
    func testUnknownWeightKeysAreIgnored() throws {
        let corpus = try Self.loadCorpus()
        let scenario = try XCTUnwrap(corpus.scenarios.first { $0.id == "unknown-weight-ignored" })
        try assertParity(scenario)
        XCTAssertEqual(scenario.expected.selectedIndex, 2)
        XCTAssertEqual(try XCTUnwrap(scenario.expected.error), 0.0234375, accuracy: 1e-12)
    }

    func testExactMatchWinsWithZeroError() throws {
        let corpus = try Self.loadCorpus()
        let scenario = try XCTUnwrap(corpus.scenarios.first { $0.id == "exact-match-zero-error" })
        try assertParity(scenario)
        XCTAssertEqual(scenario.expected.selectedIndex, 0)
        XCTAssertEqual(try XCTUnwrap(scenario.expected.error), 0, accuracy: 1e-12)
    }

    // MARK: - Solver-level replay

    /// The scorer parity above is necessary but not sufficient: the solver
    /// owns tie-breaking and exclusion in production. Scenarios whose target
    /// has every positively-weighted channel (all but `missing-target-excluded`,
    /// which no source-grid configuration can express) are replayed through
    /// `CompositionSolver` on a 1×1 grid and must select identically.
    func testSolverReplayAgreesWithCorpusSelections() throws {
        let corpus = try Self.loadCorpus()
        for scenario in corpus.scenarios where Self.isSolverExpressible(scenario) {
            let palette = try scenario.palette.map { try Self.makeColor($0) }
            let weights = Self.makeWeights(scenario.weights)
            let grids = try Self.makeGrids(for: scenario)
            let result = try CompositionSolver().solve(
                palette: palette,
                sourceGrids: grids,
                weights: weights
            )
            if let selectedIndex = scenario.expected.selectedIndex {
                XCTAssertEqual(
                    result.colorIndex(x: 0, y: 0), selectedIndex,
                    "scenario \(scenario.id): solver selection"
                )
                if let expectedError = scenario.expected.error {
                    XCTAssertEqual(result.error(x: 0, y: 0), expectedError, accuracy: 1e-12, "scenario \(scenario.id): solver error")
                }
            } else {
                XCTAssertNil(result.colorIndex(x: 0, y: 0), "scenario \(scenario.id): no candidate may match")
                XCTAssertTrue(result.error(x: 0, y: 0).isInfinite, "scenario \(scenario.id): unmatched cell error must be infinite")
                XCTAssertEqual(result.unmatchedCellCount, 1, "scenario \(scenario.id): the single cell must be unmatched")
            }
        }
    }

    private static func isSolverExpressible(_ scenario: ParityScenario) -> Bool {
        let targetKeys = Set(scenario.target.channels.keys)
        let weights = makeWeights(scenario.weights)
        return weights.activeConditions.allSatisfy { targetKeys.contains($0.rawValue) }
    }

    private static func makeGrids(for scenario: ParityScenario) throws -> [LightingCondition: BrightnessGrid] {
        let target = makeTarget(scenario.target)
        var grids: [LightingCondition: BrightnessGrid] = [:]
        for entry in makeWeights(scenario.weights).activeEntries {
            let value = try XCTUnwrap(
                target.value(for: entry.condition),
                "scenario \(scenario.id): target value for \(entry.condition)"
            )
            grids[entry.condition] = BrightnessGrid(width: 1, height: 1, values: [value])
        }
        return grids
    }
}

// MARK: - Corpus wire model

/// The corpus is decoded with its own model so a fixture that stops matching
/// this shape fails decoding loudly instead of silently testing nothing.
/// Field names use the fixture's exact snake_case keys via CodingKeys (no
/// key-conversion strategy), so the decoder is independent of the API client's.
private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let lightSources: [String]
    let missingPolicy: String
    let scorer: String
    let selection: String
    let scenarios: [ParityScenario]

    enum CodingKeys: String, CodingKey {
        case algorithmVersion = "algorithm_version"
        case lightSources = "light_sources"
        case missingPolicy = "missing_policy"
        case scorer
        case selection
        case scenarios
    }
}

private struct ParityScenario: Decodable {
    let id: String
    let description: String
    let palette: [ParityVector]
    let target: ParityVector
    let weights: [String: Double]
    let expected: ParityExpectation
}

private struct ParityVector: Decodable {
    let index: Int?
    let hexColor: String
    let channels: [String: Double]

    enum CodingKeys: String, CodingKey {
        case index
        case hexColor = "hex_color"
        case channels
    }
}

private struct ParityExpectation: Decodable {
    let scores: [ParityExpectedScore]
    let selectedIndex: Int?
    let selectedHexColor: String?
    let error: Double?
    let tieBroke: Bool?
    let tiedIndices: [Int]

    enum CodingKeys: String, CodingKey {
        case scores
        case selectedIndex = "selected_index"
        case selectedHexColor = "selected_hex_color"
        case error
        case tieBroke = "tie_broke"
        case tiedIndices = "tied_indices"
    }
}

private struct ParityExpectedScore: Decodable {
    let index: Int
    let score: ParityScore
}

/// A corpus score is either a number or the literal string `"excluded"`.
private enum ParityScore: Decodable, Equatable {
    case score(Double)
    case excluded

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .score(value)
        } else if let literal = try? container.decode(String.self), literal == "excluded" {
            self = .excluded
        } else {
            throw DecodingError.dataCorruptedError(
                in: container,
                debugDescription: "Corpus score must be a number or \"excluded\""
            )
        }
    }
}
